import json

files = {
    'unconstrained': 'outputs/w5_lora_scierc_unconstrained_eval.jsonl',
    'grammar_only': 'outputs/w7_qwen_scierc_ft_grammar_only.jsonl',
    'semantic_only': 'outputs/w7_qwen_scierc_ft_semantic_only.jsonl',
    'full_s1': 'outputs/w5_lora_scierc_full_s1_eval.jsonl',
}

data = {}
for mode, path in files.items():
    data[mode] = {}
    with open(path) as f:
        for line in f:
            d = json.loads(line)
            data[mode][d['doc_id']] = d['raw_output']

# Check how many have identical raw_output
doc_ids = list(data['unconstrained'].keys())[:20]
same_count = 0
diff_count = 0
for did in doc_ids:
    outputs = set()
    for mode in files:
        outputs.add(data[mode].get(did, ''))
    if len(outputs) == 1:
        same_count += 1
    else:
        diff_count += 1
        # Show a diff example
        if diff_count <= 2:
            print(f'=== {did} differs ===')
            for mode in files:
                print(f'  {mode}: {data[mode].get(did, \"\")[:100]}...')

print(f'First 20 docs: {same_count} identical, {diff_count} different')

# Full count
total_same = 0
total_diff = 0
for did in data['unconstrained']:
    outputs = set()
    for mode in files:
        outputs.add(data[mode].get(did, ''))
    if len(outputs) == 1:
        total_same += 1
    else:
        total_diff += 1
print(f'All docs: {total_same} identical, {total_diff} different')
